def compute(vars):
    pretax_gain = vars["v1"]
    after_tax_gain = vars["v2"]
    tax_amount = pretax_gain - after_tax_gain

    if pretax_gain == 0:
        return {"value": None, "trace": {
            "pretax_gain": pretax_gain,
            "after_tax_gain": after_tax_gain,
            "tax_amount": tax_amount,
            "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
        }}

    tax_rate = tax_amount / pretax_gain * 100
    return {"value": tax_rate, "trace": {
        "pretax_gain": pretax_gain,
        "after_tax_gain": after_tax_gain,
        "tax_amount": tax_amount,
        "output_meta": {"currency": None, "scale": "ones", "unit": "percentage"}
    }}
